import 'package:aves/model/tags/tag_path.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

// Built-in list of known characters as nested tags,
// e.g. `Blue Archive|Millennium|C&C|Asuna`, bundled in `assets/tag_catalog_*.txt`
// and generated by `tools/tag_catalog/build.py`.
//
// Catalog tags are offered in the tag editor even before being used,
// and help converting flat tags to their full path.
class TagCatalog {
  static const _assets = [
    'assets/tag_catalog_azur_lane.txt',
    'assets/tag_catalog_blue_archive.txt',
    'assets/tag_catalog_genshin.txt',
    'assets/tag_catalog_hsr.txt',
    'assets/tag_catalog_nikke.txt',
    'assets/tag_catalog_zzz.txt',
  ];

  static final TagCatalog instance = TagCatalog._private();

  final ValueNotifier<bool> loadedNotifier = ValueNotifier(false);

  // catalog entries, and all their parent paths
  Set<String> _tags = {};

  // `franchise\u0000name` in lower case -> full path
  Map<String, String> _byFranchiseAndName = {};

  Future<void>? _loading;

  new _private();

  Set<String> get tags => _tags;

  Future<void> ensureLoaded() => _loading ??= _load();

  Future<void> _load() async {
    final entries = <String>{};
    for (final asset in _assets) {
      try {
        final content = await rootBundle.loadString(asset);
        entries.addAll(content.split('\n').map((v) => v.trim()).where((v) => v.isNotEmpty && !v.startsWith('#')).map(TagPath.normalize));
      } catch (error) {
        // a missing file only means that franchise is not covered yet
        debugPrint('failed to load tag catalog asset=$asset error=$error');
      }
    }

    final byFranchiseAndName = <String, String>{};
    // characters first, then groups (e.g. `C&C` -> `Blue Archive|Millennium|C&C`),
    // keeping the first one in case of homonyms
    for (final entry in entries) {
      byFranchiseAndName.putIfAbsent(_key(TagPath.root(entry), TagPath.leaf(entry)), () => entry);
    }
    for (final entry in entries) {
      final ancestors = TagPath.selfAndAncestors(entry);
      for (final ancestor in ancestors.skip(1).take(ancestors.length - 2)) {
        byFranchiseAndName.putIfAbsent(_key(TagPath.root(ancestor), TagPath.leaf(ancestor)), () => ancestor);
      }
    }

    _tags = TagPath.expand(entries);
    _byFranchiseAndName = byFranchiseAndName;
    loadedNotifier.value = true;
  }

  // full catalog path for a character or group of a franchise, if known,
  // e.g. (`Blue Archive`, `asuna`) -> `Blue Archive|Millennium|C&C|Asuna`
  String? find(String franchise, String name) => _byFranchiseAndName[_key(franchise, name)];

  static String _key(String franchise, String name) => '${franchise.trim().toLowerCase()}\u0000${name.trim().toLowerCase()}';
}
